import JSON

"""
	gen( x, mu, s, name )

Generate fixture data and write to file.

The log-density is evaluated in extended precision from the textbook formula `ln((1 + cos(pi*z)) / (2s))`, with `z = (x-mu)/s`.

# Arguments

* `x`: input value
* `mu`: location parameter
* `s`: scale parameter
* `name::AbstractString`: output filename

# Examples

``` julia
julia> x = rand( 1000 ) .* 15;
julia> mu = rand( 1000 ) .* 10.0;
julia> s = rand( 1000 ) .* 5.0;
julia> gen( x, mu, s, "data.json" );
```
"""
function gen( x, mu, s, name )
	z = setprecision( BigFloat, 2048 ) do
		zz = ( BigFloat.( x ) .- BigFloat.( mu ) ) ./ BigFloat.( s );
		Float64.( log.( ( 1 .+ cos.( BigFloat( pi ) .* zz ) ) ./ ( 2 .* BigFloat.( s ) ) ) )
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("mu", mu),
		("s", s),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Negative mean (`x` inside the support):
mu = rand( 1000 ) .* -10.0;
s = ( rand( 1000 ) .* 5.0 ) .+ 0.1;
x = mu .+ ( s .* ( ( rand( 1000 ) .* 2.0 ) .- 1.0 ) );
gen( x, mu, s, "negative_mean.json" );

# Positive mean (`x` inside the support):
mu = rand( 1000 ) .* 10.0;
s = ( rand( 1000 ) .* 5.0 ) .+ 0.1;
x = mu .+ ( s .* ( ( rand( 1000 ) .* 2.0 ) .- 1.0 ) );
gen( x, mu, s, "positive_mean.json" );

# Large variance (`x` inside the support):
mu = rand( 1000 );
s = ( rand( 1000 ) .* 20.0 ) .+ 1.0;
x = mu .+ ( s .* ( ( rand( 1000 ) .* 2.0 ) .- 1.0 ) );
gen( x, mu, s, "large_variance.json" );

# Close to the edges of the support (`mu = 0` and `s` a power of two, so that `z = x/s` is exact and the test measures the error from `1 + cos(pi*z)`):
s = repeat( [ 0.5, 1.0, 2.0, 4.0 ], 250 );
d = exp10.( range( -15.0, stop = -1.0, length = 500 ) );
x = s .* vcat( 1.0 .- d, -1.0 .+ d );
mu = zeros( 1000 );
gen( x, mu, s, "edges.json" );
